mapper.select:
select m.msg_id, m.recipient_id, m.mode, m.category, m.title,

       case when m.biz_type = 'chat_conv' then '（私信 / 群聊内容不在后台展示）' else m.content end as content,
       m.biz_type, m.biz_id,
       m.route, m.read_flag, m.read_time, m.del_flag, m.create_time, u.nickname
from kg_message m

left join kg_app_user u on u.user_id = m.recipient_id and u.del_flag = '0'

    m.del_flag = '0'
     and m.recipient_id = #{recipientId}
     and m.mode = #{mode}
     and m.category = #{category}
     and m.title like concat('%', #{title}, '%')
     and m.read_flag = #{readFlag}
     and m.biz_type = #{bizType}
     and m.biz_id = #{bizId}
     and u.nickname like concat('%', #{nickname}, '%')

        and date_format(m.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')


        and date_format(m.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')


order by m.msg_id desc

